# A script to test the output limit of the review command.
# It prints a large number of uniquely identifiable lines.

def main():
    total_lines = 10000
    print("--- BEGINNING OUTPUT LIMIT TEST ---")
    for i in range(1, total_lines + 1):
        print(f"Line {i} of {total_lines}")
    print("--- END OF OUTPUT LIMIT TEST ---")

if __name__ == "__main__":
    main()
